const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const text = String(input.text || input.message_text || input.texto_mensaje || '').trim();
const textLower = text.toLowerCase();

const requestId = input.request_id || "req_${Date.now()}_${Math.floor(Math.random() * 100000)}";
const role = input.role || 'professional';

let route = 'unknown';
let confidence = 0.5;
let reply = 'He recibido tu mensaje. Lo estoy analizando...';

if (/\b(cita|agendar|agenda|reservar|reserva|hueco|hora|calendario|consulta|visita|disponibilidad)\b/i.test(textLower)) {
  route = 'appointment';
  confidence = 0.95;
  reply = 'He recibido tu solicitud de cita. Ahora mismo compruebo la agenda y te confirmo las opciones disponibles.';
} else if (/\b(ejercicio|ejercicios|estiramiento|estiramientos|rutina|movilidad|fortalecimiento|plan|tabla|pauta|entrenar)\b/i.test(textLower)) {
  route = 'exercise';
  confidence = 0.95;
  reply = 'Entendido. Voy a procesar el caso y a preparar un plan de ejercicios personalizado. Esto tomará unos segundos...';
} else if (/\b(dolor|sintoma|sintomas|molestia|lesion|evolucion|seguimiento|mejora|empeorado|noto|duele|pinchazo)\b/i.test(textLower)) {
  route = 'session_note';
  confidence = 0.85;
  reply = 'He registrado la evolución clínica en el historial para tenerlo en cuenta durante el tratamiento.';
} else if (text.length <= 2) {
  route = 'unknown';
  confidence = 0.1;
  reply = 'No he podido entender el mensaje. ¿Puedes darme más detalles?';
} else {
  route = 'fallback';
  confidence = 0.3;
  reply = 'He anotado tu mensaje en el sistema para revisarlo en detalle.';
}

return [{
  json: {
    ok: true,
    request_id: requestId,
    role,
    route,
    confidence,
    reply_text: reply,
    intent_hint: route,
    normalized_payload: {
      text,
      channel: input.channel || 'web',
      patient_id: input.paciente_id || input.patient_id || null,
      professional_id: input.profesional_id || input.professional_id || null
    },
    received: {
      channel: input.channel || 'web',
      paciente_id: input.paciente_id || input.patient_id || null,
      profesional_id: input.profesional_id || input.professional_id || null,
      text
    }
  }
}];
